import asyncio
async def handle(r,w):
    while await r.readline(): w.write(b':huddle 421 * UNKNOWN :Unknown command\r\n'); await w.drain()
async def main():
    s=await asyncio.start_server(handle,'0.0.0.0',6667)
    async with s: await s.serve_forever()
asyncio.run(main())
